#!/bin/sh
# Runs the script against every lab case and writes a formatted results file.
# -sV is needed so the http portrule matches the non-standard lab ports.
#
# Output: results/lab-run-<UTC timestamp>.txt, generated by report.py from the
# scan XML, so the results table is machine-made rather than typed up. That
# directory is gitignored; promote a run into ../../tests/ to record it.
# Exits non-zero if any case does not match cases.tsv.
set -e
cd "$(dirname "$0")"

# Prerequisites: Docker, Nmap and python3.
for tool in docker nmap python3; do
  command -v "$tool" >/dev/null 2>&1 || { echo "$tool not found; the lab needs Docker, Nmap and python3" >&2; exit 1; }
done

SCRIPT=../../nse/http-vuln-cve2026-123007.nse
PORTS=8441-8446,8080,8448,8449
STAMP=$(date -u +%Y-%m-%dT%H%M%SZ)
mkdir -p results
OUT=results/lab-run-$STAMP.txt
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

# Environment facts the report prints, as key=value.
{
  printf 'Docker=%s\n' "$(docker --version 2>/dev/null | sed 's/^Docker version //;s/,.*//')"
  printf 'Docker Compose=%s\n' "$(docker compose version --short 2>/dev/null)"
  printf 'Host=%s %s %s\n' "$(uname -s)" "$(uname -r)" "$(uname -m)"
  printf 'Containers=%s\n' "$(docker compose ps --format '{{.Service}}:{{.Image}}' 2>/dev/null | sort | tr '\n' ' ')"
} > "$WORK/env.txt"

echo "Scanning $PORTS on 127.0.0.1 ..."
nmap -Pn -n -sT -sV --version-light \
  -p "$PORTS" \
  --script "$SCRIPT" --script-args vulns.showall \
  -oX "$WORK/scan.xml" \
  127.0.0.1 > "$WORK/scan.txt"

python3 report.py "$WORK/scan.xml" cases.tsv \
  --env "$WORK/env.txt" --full "$WORK/scan.txt" > "$OUT"
STATUS=$?

cat "$OUT"
echo
echo "Written to $OUT"
exit $STATUS
